SELECT NVL((
           SELECT CASE WHEN B.MNG_ID = A.ID THEN 'Y' ELSE 'N' END
             FROM TB_CM06M01 A
             JOIN TB_CM06M01 B ON B.ID = #{draUserId}
            WHERE A.ID = #{approverId}
       ), 'N')
  FROM DUAL

mapper.update:
UPDATE TB_AM11M01 SET DOC_TITLE = #{docTitle}, DOC_STATUS = #{docStatus},
DRAFT_DT = NVL(DRAFT_DT, SYSDATE),
CURR_LINE_SEQ = #{currLineSeq, jdbcType=INTEGER}, CURR_APPROVER_ID = #{currApproverId, jdbcType=VARCHAR}, CURR_APPROVER_NM = #{currApproverNm, jdbcType=VARCHAR}, SECURITY_LEVEL = NVL(#{securityLevel, jdbcType=VARCHAR}, SECURITY_LEVEL), RETENTION_PERIOD = NVL(#{retentionPeriod, jdbcType=VARCHAR}, RETENTION_PERIOD), DOC_DATA_JSON = #{docDataJson, jdbcType=CLOB}, DOC_RENDER_HTML = #{docRenderHtml, jdbcType=CLOB}, ERP_BIZ_TYPE = #{erpBizType, jdbcType=VARCHAR}, ERP_BIZ_KEY = #{erpBizKey, jdbcType=VARCHAR}, UDT_ID = #{userId}, UDT_PGM = #{pgmId}, UDT_DTTM = SYSDATE WHERE DOC_ID = #{docId}

UPDATE TB_AM11M01 SET DOC_STATUS = #{nextStatus}, CURR_LINE_SEQ = #{currLineSeq, jdbcType=INTEGER}, CURR_APPROVER_ID = #{currApproverId, jdbcType=VARCHAR}, CURR_APPROVER_NM = #{currApproverNm, jdbcType=VARCHAR},
COMPLETE_DT = SYSDATE,
UDT_ID = #{userId}, UDT_PGM = #{pgmId}, UDT_DTTM = SYSDATE WHERE DOC_ID = #{docId}

UPDATE TB_WB20M03
   SET SANCTN_STTUS='N', TODO_CF_DT=NULL, TODO_CF_OPN=NULL,
       APPR_REJECT_YN='N', UDT_ID=#{userId}, UDT_PGM=#{pgmId}, UDT_DTTM=SYSDATE
 WHERE CO_CD=#{coCd} AND TODO_NO=#{erpBizKey}
   AND SANCTN_SN >= #{wb20SanctnSn}
   AND NVL(SANCTN_STTUS,'N')='Y'

UPDATE TB_WB20M03 SET SANCTN_STTUS = 'Y', TODO_CF_DT = SYSDATE, TODO_CF_OPN = NVL(#{apprOpinion, jdbcType=VARCHAR}, '상위 결재자 전결로 인한 종결'), UDT_ID = #{userId}, UDT_PGM = 'AM11_ARBIT', UDT_DTTM = SYSDATE WHERE TODO_NO = #{erpBizKey}
AND TODO_DIV2_CODE_ID = #{todoDiv2CodeId}
AND SANCTN_SN > #{wb20SanctnSn}
AND NVL(SANCTN_STTUS, 'N') != 'Y'

mapper.delete:
DELETE FROM TB_AM11D01
 WHERE DOC_ID = #{docId}
   AND LINE_STATUS IN ('READY', 'PENDING')
   AND LINE_SEQ >= #{currLineSeq}

mapper.select:
SELECT AUTH_INFO
  FROM TB_CM06M01
 WHERE ID = #{userId}

SELECT DOC_ID
  FROM (
        SELECT D.DOC_ID
          FROM TB_AM11D01 D
         WHERE D.WB20_TODO_KEY = #{todoKey, jdbcType=VARCHAR}
         UNION ALL
        SELECT M.DOC_ID
          FROM TB_AM11M01 M
         WHERE M.ERP_BIZ_KEY = #{erpBizKey, jdbcType=VARCHAR}

           AND M.CO_CD = #{coCd, jdbcType=VARCHAR}


           AND (
               EXISTS (
                   SELECT 1 FROM TB_AM11D01 D2
                    WHERE D2.DOC_ID = M.DOC_ID
                      AND D2.WB20_DIV2_CODE_ID = #{todoDiv2CodeId, jdbcType=VARCHAR}
               )
               OR M.ERP_BIZ_TYPE IN ('PM51', 'PM07', 'PM08')
           )

         ORDER BY TO_NUMBER(DOC_ID) DESC
       )
 WHERE ROWNUM = 1
